<?php
namespace App\Http\Controllers;
use App\Models\MediaFile;use App\Models\MediaStatusHistory;use App\Models\SystemSetting;use App\Services\AuditService;use App\Services\MediaAccessService;use App\Services\SearchIndexService;use Illuminate\Http\Request;
class LifecycleWorkflowController extends Controller {
 public function transition(Request $r,MediaFile $mediaFile,MediaAccessService $access,AuditService $audit,SearchIndexService $search){abort_unless($access->canManageLifecycle($mediaFile,$r->user()),403);$d=$r->validate(['status'=>'required|in:draft,review,approved,published,archived','note'=>'nullable|string|max:1000']);$from=strtolower((string)($mediaFile->asset_status?:'draft'));$to=$d['status'];$allowed=SystemSetting::valueFor('lifecycle.settings',[])['transitions'][$from]??[];abort_unless(in_array($to,$allowed,true),422,'Lifecycle transition is not allowed.');$this->validateMetadata($mediaFile,$to);$mediaFile->forceFill(['asset_status'=>$to,'archived_at'=>$to==='archived'?now():null,'archived_by'=>$to==='archived'?$r->user()->id:null])->save();MediaStatusHistory::create(['media_file_id'=>$mediaFile->id,'from_status'=>$from,'to_status'=>$to,'note'=>$d['note']??null,'changed_by'=>$r->user()->id]);$audit->log($r,'media.lifecycle.transitioned',$mediaFile,'Media lifecycle transitioned.',['from'=>$from,'to'=>$to,'note'=>$d['note']??null]);$search->upsert($mediaFile->fresh(['category','subcategory','department']));return back()->with('success','Lifecycle status updated.');}
 private function validateMetadata(MediaFile $m,string $to): void {if(!in_array($to,['approved','published'],true))return;$base=SystemSetting::valueFor('metadata.settings',[])['required_fields']??[];$typed=SystemSetting::valueFor('metadata.type_required',[])[$m->type]??[];foreach(array_unique(array_merge($base,$typed)) as $field)abort_if(blank(data_get($m,$field)),422,"Required metadata missing: {$field}");}
}
